import json
def main(result: list) -> dict:
    if not isinstance(result, list) or len(result) > 3: raise ValueError('Unexpected legal retrieval result')
    sources=[]
    for row in result:
        if not isinstance(row, dict) or not isinstance(row.get('content'), str) or not row['content'].strip(): continue
        if len(row['content']) > 12000: raise ValueError('Legal passage exceeds this sample limit; adjust knowledgebase chunking')
        metadata=row.get('metadata') or {}
        if not isinstance(metadata, dict): raise ValueError('Invalid legal source metadata')
        sources.append({'id':'L'+str(len(sources)+1),'title':str(row.get('title') or metadata.get('document_name') or 'Untitled source')[:300],'content':row['content'],'metadata':{k:str(metadata[k])[:500] for k in ['dataset_id','document_id','segment_id','document_name','jurisdiction','law_title','article','effective_date','version','source_url'] if k in metadata}})
    context=json.dumps(sources,ensure_ascii=False)
    if len(context)>45000: raise ValueError('Retrieved law exceeds sample context limit')
    return {'context':context,'has_sources':'yes' if sources else 'no'}

