import json
def main(answer: str, context: str) -> dict:
    sources=json.loads(context); allowed={s['id'] for s in sources}
    if not allowed: raise ValueError('Legal analysis needs retrieved sources')
    if not isinstance(answer,str) or len(answer)>40000: raise ValueError('Invalid analysis size')
    data=json.loads(answer)
    if not isinstance(data,dict) or set(data)!={'analysis','questions','limitations'}: raise ValueError('Invalid analysis format')
    lines=[]
    for key in ['analysis','questions','limitations']:
        items=data[key]
        if not isinstance(items,list) or len(items)>12: raise ValueError('Invalid analysis list')
        lines.append('\n'+key.title())
        for item in items:
            if key=='analysis':
                if not isinstance(item,dict) or set(item)!={'text','citations'}: raise ValueError('Invalid legal assertion')
                text=item['text']; citations=item['citations']
                if not isinstance(citations,list) or not citations or len(citations)>6 or any(not isinstance(c,str) or c not in allowed for c in citations): raise ValueError('Unknown or missing legal citation')
                suffix=' '+''.join('['+c+']' for c in dict.fromkeys(citations))
            else: text=item; suffix=''
            if not isinstance(text,str) or not text.strip() or len(text)>2000: raise ValueError('Invalid analysis text')
            lines.append('- '+text+suffix)
    text='\n'.join(lines)
    if len(text)>2000: raise ValueError('Analysis exceeds brief limit')
    return {'text':text}

